        function.instruction(&Instruction::LocalGet(candidate_index_local));
        function.instruction(&Instruction::LocalGet(index_local));
        function.instruction(&Instruction::I64GeU);
        function.instruction(&Instruction::LocalGet(candidate_index_local));
