            self.store_i64_local_at_offset(
                receiver_payload_local,
                HEAP_LEN_OFFSET,
                index_local,
                function,
            );
            function.instruction(&Instruction::End);
            self.release_temp_local(index_local);
            self.release_temp_local(len_local);
            self.release_temp_local(receiver_tag_local);
